import json
import re
import sys

preflightStatus = "helper-failure"
preflightStatusCode = "500"
preflightMessage = "Active-backup preflight inspection did not complete."
preflightResultJson = json.dumps({"error": preflightMessage}, separators=(",", ":"))
MOID_PATTERN = re.compile(r"^[0-9a-fA-F]{24}$")

def validate_ref(value, expected_moid, expected_type, label):
    if not isinstance(value, dict) or value.get("Moid") != expected_moid:
        raise ValueError(label + " relationship does not preserve the expected Moid.")
    if value.get("ObjectType") != expected_type or value.get("ClassId") not in ("mo.MoRef", expected_type):
        raise ValueError(label + " relationship discriminators are invalid.")

try:
    payload = json.loads(sys.argv[1])
    deviceMoid = sys.argv[2]
    organizationMoid = sys.argv[3]
    if not MOID_PATTERN.fullmatch(deviceMoid) or not MOID_PATTERN.fullmatch(organizationMoid):
        raise ValueError("Resolved preflight relationship Moids are malformed.")
    if not isinstance(payload, dict) or not isinstance(payload.get("Results"), list):
        raise ValueError("Backup preflight response must contain a Results array.")
    results = payload["Results"]
    count = payload.get("Count")
    if isinstance(count, bool) or not isinstance(count, int) or count < 0:
        raise ValueError("Backup preflight Count must be a nonnegative integer.")
    if count > 1000:
        raise ValueError("Backup preflight Count exceeds the supported complete-result bound of 1000.")
    if count != len(results):
        raise ValueError("Backup preflight Count does not equal Results length; the result set may be truncated.")
    seen = set()
    active = []
    historical = []
    for item in results:
        if not isinstance(item, dict):
            raise ValueError("Every preflight result must be an object.")
        moid = item.get("Moid")
        if not isinstance(moid, str) or not MOID_PATTERN.fullmatch(moid) or moid in seen:
            raise ValueError("Every preflight backup must have a unique safe Moid.")
        seen.add(moid)
        if item.get("ClassId") != "recovery.OnDemandBackup" or item.get("ObjectType") != "recovery.OnDemandBackup":
            raise ValueError("Every preflight resource must be a concrete recovery.OnDemandBackup.")
        validate_ref(item.get("DeviceId"), deviceMoid, "asset.DeviceRegistration", "DeviceId")
        validate_ref(item.get("Organization"), organizationMoid, "organization.Organization", "Organization")
        config = item.get("ConfigResult")
        if config is None or config == {}:
            active.append({"Moid": moid, "ConfigState": "not-reported"})
            continue
        if not isinstance(config, dict) or config.get("ClassId") != "recovery.ConfigResult" or config.get("ObjectType") != "recovery.ConfigResult":
            raise ValueError("ConfigResult must be expanded as a concrete recovery.ConfigResult.")
        configMoid = config.get("Moid")
        if not isinstance(configMoid, str) or not MOID_PATTERN.fullmatch(configMoid):
            raise ValueError("Expanded ConfigResult Moid is missing or malformed.")
        state = config.get("ConfigState")
        stage = config.get("ConfigStage")
        if state is None:
            state = ""
        elif not isinstance(state, str):
            raise ValueError("Expanded ConfigResult.ConfigState must be a string when present.")
        if stage is None:
            stage = ""
        elif not isinstance(stage, str):
            raise ValueError("Expanded ConfigResult.ConfigStage must be a string when present.")
        if state == "":
            active.append({"Moid": moid, "ConfigResultMoid": configMoid, "ConfigState": state, "ConfigStage": stage})
        elif state in ("Ok", "Ok-with-warning", "Errored"):
            historical.append({"Moid": moid, "ConfigState": state, "ConfigStage": stage})
        else:
            raise ValueError("ConfigResult.ConfigState contains an undocumented nonterminal value: " + state)
    if active:
        preflightStatus = "active-backup"
        preflightStatusCode = "409"
        preflightMessage = "An on-demand backup without a documented terminal ConfigState already exists for this device and organization."
        preflightResultJson = json.dumps({"error": preflightMessage, "activeBackups": active, "historicalBackupCount": len(historical)}, separators=(",", ":"))
    else:
        preflightStatus = "ready"
        preflightStatusCode = "200"
        preflightMessage = "No active on-demand backup was found for the exact registered device and organization."
        preflightResultJson = json.dumps({"activeBackupCount": 0, "historicalBackupCount": len(historical)}, separators=(",", ":"))
except Exception as exc:
    preflightStatus = "invalid-resource" if preflightStatus == "helper-failure" else preflightStatus
    preflightStatusCode = "502" if preflightStatus == "invalid-resource" else preflightStatusCode
    preflightMessage = str(exc)
    preflightResultJson = json.dumps({"error": "Active-backup preflight response validation failed", "detail": preflightMessage}, separators=(",", ":"))

import json
import re
import sys

acceptanceStatus = "helper-failure"
acceptanceStatusCode = "500"
acceptanceMessage = "Backup acceptance inspection did not complete."
acceptanceResultJson = json.dumps({"error": acceptanceMessage, "requestMayHaveBeenAccepted": True}, separators=(",", ":"))
backupMoid = ""
MOID_PATTERN = re.compile(r"^[0-9a-fA-F]{24}$")

def validate_ref(value, expected_moid, expected_type, label):
    if not isinstance(value, dict) or value.get("Moid") != expected_moid:
        raise ValueError(label + " relationship does not preserve the expected Moid.")
    if value.get("ObjectType") != expected_type or value.get("ClassId") not in ("mo.MoRef", expected_type):
        raise ValueError(label + " relationship discriminators are invalid.")

try:
    item = json.loads(sys.argv[1])
    deviceMoid = sys.argv[2]
    organizationMoid = sys.argv[3]
    if not isinstance(item, dict):
        raise ValueError("Backup POST response must be a JSON object.")
    if item.get("ClassId") != "recovery.OnDemandBackup" or item.get("ObjectType") != "recovery.OnDemandBackup":
        raise ValueError("The POST response is not a concrete recovery.OnDemandBackup.")
    moid = item.get("Moid")
    if not isinstance(moid, str) or not MOID_PATTERN.fullmatch(moid):
        raise ValueError("The created backup Moid is missing or malformed.")
    validate_ref(item.get("DeviceId"), deviceMoid, "asset.DeviceRegistration", "DeviceId")
    validate_ref(item.get("Organization"), organizationMoid, "organization.Organization", "Organization")
    backupMoid = moid
    state = "not-reported"
    stage = ""
    config = item.get("ConfigResult")
    if config not in (None, {}):
        if not isinstance(config, dict) or config.get("ObjectType") != "recovery.ConfigResult" or config.get("ClassId") not in ("mo.MoRef", "recovery.ConfigResult"):
            raise ValueError("The POST ConfigResult relationship discriminators are invalid.")
        configMoid = config.get("Moid")
        if not isinstance(configMoid, str) or not MOID_PATTERN.fullmatch(configMoid):
            raise ValueError("The POST ConfigResult relationship Moid is missing or malformed.")
        if config.get("ClassId") == "recovery.ConfigResult":
            state = config.get("ConfigState")
            stage = config.get("ConfigStage")
            if state is None:
                state = ""
            elif not isinstance(state, str):
                raise ValueError("Expanded POST ConfigResult.ConfigState must be a string when present.")
            if stage is None:
                stage = ""
            elif not isinstance(stage, str):
                raise ValueError("Expanded POST ConfigResult.ConfigStage must be a string when present.")
            if state not in ("", "Ok", "Ok-with-warning", "Errored"):
                raise ValueError("POST ConfigResult.ConfigState is undocumented: " + state)
    if state == "Errored":
        acceptanceStatus = "operation-failure"
        acceptanceStatusCode = "500"
        acceptanceMessage = "The accepted backup already reports ConfigState Errored."
    elif state == "Ok":
        acceptanceStatus = "complete"
        acceptanceStatusCode = "200"
        acceptanceMessage = "The created backup already reports ConfigState Ok."
    elif state == "Ok-with-warning":
        acceptanceStatus = "warning"
        acceptanceStatusCode = "200"
        acceptanceMessage = "The created backup already reports ConfigState Ok-with-warning."
    else:
        acceptanceStatus = "ready"
        acceptanceStatusCode = "202"
        acceptanceMessage = "The on-demand backup request was accepted; completion has not yet been verified."
    acceptanceResultJson = json.dumps({"requestAccepted": True, "completionVerified": acceptanceStatus in ("complete", "warning"), "backupMoid": moid, "configState": state, "configStage": stage, "warning": acceptanceStatus == "warning"}, separators=(",", ":"))
except Exception as exc:
    if acceptanceStatus == "helper-failure":
        acceptanceStatus = "invalid-resource"
        acceptanceStatusCode = "502"
    acceptanceMessage = str(exc)
    acceptanceResultJson = json.dumps({"error": "Backup POST response validation failed", "detail": acceptanceMessage, "requestMayHaveBeenAccepted": True}, separators=(",", ":"))
